{"explanation":"A radian is the angle you get when you walk along a circle's edge a distance equal to its radius. Since the circumference is 2π times the radius, a full turn is 2π radians (about 6.28), and one radian is roughly 57.3°. Drag the yellow dot or use the slider to change the angle and see how the arc length compares to the radius.","manimCode":"const R = 2;
const cx = -1.5, cy = 0;
const C = [cx, cy, 0];
const circle = new Circle({ radius: R, color: BLUE });
circle.moveTo(C);
scene.add(circle);

const title = new Text({ text: 'What is a radian?', color: WHITE, fontSize: 36 });
title.moveTo([0, 3.4, 0]);
await scene.play(new Write(title));

const pt = (a) => [cx + R * Math.cos(a), cy + R * Math.sin(a), 0];

// radius line along x-axis
const r0 = new Line({ start: C, end: pt(0), color: WHITE });
await scene.play(new Create(r0));
const rLabel = new Text({ text: 'r', color: WHITE, fontSize: 28 });
rLabel.moveTo([cx + R / 2, cy - 0.35, 0]);
scene.add(rLabel);

// Arc built as polygon (open path), updated live
function arcVerts(a) {
  const n = Math.max(2, Math.ceil(a * 30));
  const v = [];
  for (let i = 0; i <= n; i++) v.push(pt(a * i / n));
  return v;
}
let angle = 1;
const arc = new Polygon({ vertices: arcVerts(1), color: YELLOW });
arc.setStrokeWidth(6).setFillOpacity(0);
const radius2 = new Polygon({ vertices: [C, pt(1)], color: WHITE });
radius2.setStrokeWidth(3).setFillOpacity(0);
await scene.play(new Create(arc));
scene.add(radius2);

const dot = new Dot({ point: pt(1), color: YELLOW });
scene.add(dot);

// info text (immutable -> recreate)
let info = null;
function updateInfo() {
  if (info) scene.remove(info);
  const deg = (angle * 180 / Math.PI).toFixed(1);
  info = new Text({
    text: 'θ = ' + angle.toFixed(2) + ' rad = ' + deg + '°\narc = ' + angle.toFixed(2) + ' × r',
    color: YELLOW, fontSize: 26
  });
  info.moveTo([4, 1, 0]);
  scene.add(info);
}
updateInfo();

function setAngle(a) {
  angle = Math.min(2 * Math.PI, Math.max(0.05, a));
  arc.setVertices(arcVerts(angle));
  radius2.setVertices([C, pt(angle)]);
  dot.moveTo(pt(angle));
  updateInfo();
}

// Animate the 1 radian unrolling: show r copies of radius
const note = new Text({ text: '1 radian: arc length = radius', color: YELLOW, fontSize: 26 });
note.moveTo([4, 2.5, 0]);
await scene.play(new Write(note));
await scene.wait(1);

// sweep animation through 2π
const tr = new ValueTracker(1);
tr.addUpdater(() => {});
for (let k = 1; k <= 6; k++) {
  const target = k;
  const steps = 20;
  const start = angle;
  for (let i = 1; i <= steps; i++) {
    setAngle(start + (target - start) * i / steps);
    await scene.wait(0.02);
  }
  await scene.wait(0.4);
}
for (let i = 1; i <= 20; i++) {
  setAngle(6 + (2 * Math.PI - 6) * i / 20);
  await scene.wait(0.02);
}
const full = new Text({ text: 'Full circle = 2π ≈ 6.28 radians', color: GREEN, fontSize: 24 });
full.moveTo([4, -1.2, 0]);
await scene.play(new Write(full));

// interactivity: slider
const controls = new Controls(scene, { position: 'bottom-right' });
controls.addSlider({ label: 'Angle (rad)', min: 0.05, max: 6.28, value: angle, step: 0.01, onChange: (v) => setAngle(v) });

await scene.wait(999999);"}

